#!/usr/bin/env python3

def foo(x, y, z, w):
    if isinstance(x, int):
        x, y, z, w = bytes([x]), bytes([y]), bytes([z]), bytes([w])
    return bytes([(a&b&c&d | a&(b^255)&(c^255)&d | a&(b^255)&c&(d^255) | a&b&(c^255)&(d^255) | (a^255)&b&(c^255)&d | (a^255)&b&c&(d^255)) for a, b, c, d in zip(x, y, z, w)])

# Create truth table for one bit of the function to understand its behavior
print("Truth table for foo function (single bit):")
print("a b c d | output")
print("---------+-------")
for a in range(2):
    for b in range(2):
        for c in range(2):
            for d in range(2):
                result = a&b&c&d | a&(b^1)&(c^1)&d | a&(b^1)&c&(d^1) | a&b&(c^1)&(d^1) | (a^1)&b&(c^1)&d | (a^1)&b&c&(d^1)
                print(f"{a} {b} {c} {d} | {result}")

# Test with some basic inputs
print("\nBasic foo function tests:")
print(f"foo(0,0,0,0) = {foo(0,0,0,0).hex()}")
print(f"foo(255,255,255,255) = {foo(255,255,255,255).hex()}")
print(f"foo([255,0,255,0], [0,255,255,0], [0,0,255,255], [255,255,0,0]) = {foo(bytes([255,0,255,0]), bytes([0,255,255,0]), bytes([0,0,255,255]), bytes([255,255,0,0])).hex()}")

# Analyze the function to see if it matches any known binary operations
print("\nAnalyzing foo logic...")
def xor(a, b, c, d):
    return a ^ b ^ c ^ d

def and_op(a, b, c, d):
    return a & b & c & d

def or_op(a, b, c, d):
    return a | b | c | d

test_inputs = [
    (0, 0, 0, 0),
    (255, 0, 0, 0),
    (0, 255, 0, 0),
    (255, 255, 0, 0),
    (0, 0, 255, 0),
    (255, 0, 255, 0),
    (0, 255, 255, 0),
    (255, 255, 255, 0),
    (0, 0, 0, 255),
    (255, 0, 0, 255),
]

for a, b, c, d in test_inputs:
    foo_result = foo(a, b, c, d)[0]
    xor_result = xor(a, b, c, d)
    and_result = and_op(a, b, c, d)
    or_result = or_op(a, b, c, d)

    print(f"Inputs: {a}, {b}, {c}, {d}")
    print(f"  foo result: {foo_result}")
    print(f"  XOR result: {xor_result}")
    print(f"  AND result: {and_result}")
    print(f"  OR result: {or_result}")
    print(f"  Matches XOR: {foo_result == xor_result}")
    print(f"  Matches AND: {foo_result == and_result}")
    print(f"  Matches OR: {foo_result == or_result}")

# Check if the function is invertible (one-to-one)
print("\nTesting if foo is invertible...")
outputs = {}
for a in range(0, 256, 255):
    for b in range(0, 256, 255):
        for c in range(0, 256, 255):
            for d in range(0, 256, 255):
                output = foo(a, b, c, d)[0]
                if output not in outputs:
                    outputs[output] = []
                outputs[output].append((a, b, c, d))

for output, inputs in outputs.items():
    if len(inputs) > 1:
        print(f"Output {output} has multiple inputs: {inputs}")

if any(len(inputs) > 1 for inputs in outputs.values()):
    print("foo is not invertible (many-to-one mapping)")
else:
    print("foo is invertible (one-to-one mapping)")
